cards.css:
.rui-flight .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-flight .rui-main { width: 560px; margin: 14px auto; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-flight .route { display: flex; align-items: center; gap: 18px; padding: 14px 20px; background: #0a1428; color: #fff; }
.rui-flight .code { display: grid; }
.rui-flight .code b { font: 600 26px/1 ui-monospace, Menlo, monospace; }
.rui-flight .code small { color: #94a3b8; font-size: 12px; margin-top: 3px; }
.rui-flight .arrow { flex: 1; text-align: center; color: #64748b; }
.rui-flight .when { display: grid; text-align: right; font-size: 12px; color: #cbd5e1; }
.rui-flight .sky { display: block; width: 100%; height: 192px; background: linear-gradient(180deg, #0b1440, #1e3a8a); }
.rui-flight .results { padding: 4px 20px 12px; }
.rui-flight .status { display: flex; justify-content: space-between; margin: 10px 0; }
.rui-flight .status span { color: #6b7280; }
.rui-flight .flight { display: grid; grid-template-columns: 34px 46px 1fr 46px 52px auto; gap: 10px; align-items: center; border: 1px solid #e5e9f0; border-radius: 6px; padding: 9px 12px; margin-bottom: 8px; }
.rui-flight .airline { width: 34px; height: 34px; border-radius: 4px; display: grid; place-items: center; color: #fff; font: 700 12px system-ui; }
.rui-flight .stops { font-size: 12px; color: #6b7280; text-align: center; }
.rui-flight .price { font-size: 16px; }
.rui-flight .flight button { border: 0; border-radius: 4px; padding: 7px 12px; background: #0a1428; color: #fff; font: 600 13px system-ui; }

.rui-delivery { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-delivery .tracker { width: 380px; margin: 14px auto; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-delivery .order { display: flex; justify-content: space-between; padding: 12px 16px; border-bottom: 1px solid #eef0f3; }
.rui-delivery .order small { color: #6b7280; }
.rui-delivery .ride { display: block; width: 100%; height: 250px; padding: 6px 24px 0; box-sizing: border-box; background: linear-gradient(180deg, #fff7ed, #fff); }
.rui-delivery .eta { display: flex; align-items: baseline; gap: 10px; margin: 6px 16px 2px; }
.rui-delivery .eta b { font-size: 20px; }
.rui-delivery .eta span { color: #6b7280; }
.rui-delivery .track { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; list-style: none; margin: 8px 16px 4px; padding: 0; font-size: 12px; color: #6b7280; }
.rui-delivery .track li::before { content: ""; display: block; height: 4px; border-radius: 2px; background: #e5e7eb; margin-bottom: 5px; }
.rui-delivery .track .done::before, .rui-delivery .track .now::before { background: #f97316; }
.rui-delivery .track .done, .rui-delivery .track .now { color: #111827; font-weight: 600; }
.rui-delivery .courier { display: grid; grid-template-columns: 38px 1fr auto; gap: 10px; align-items: center; padding: 10px 16px 14px; }
.rui-delivery .courier i { width: 38px; height: 38px; border-radius: 50%; background: linear-gradient(135deg, #fcd34d, #f97316); }
.rui-delivery .courier small { display: block; color: #6b7280; font-size: 12px; }
.rui-delivery .courier button { border: 1px solid #d1d5db; border-radius: 8px; background: #fff; color: #111827; padding: 7px 14px; font: 600 13px system-ui; }
.rui-delivery .details { width: 380px; margin: 0 auto 1100px; }
.rui-delivery .details h2 { font-size: 16px; }
.rui-delivery .details p { margin: 0; padding: 10px 0; border-bottom: 1px solid #e5e7eb; }

.rui-payment .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-payment .rui-main { width: 560px; margin: 14px auto; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-payment .head { display: flex; justify-content: space-between; align-items: center; padding: 14px 20px; background: #0a1428; color: #fff; }
.rui-payment .head small { display: block; font: 600 11px system-ui; letter-spacing: .1em; color: #94a3b8; }
.rui-payment .head b { font-size: 15px; }
.rui-payment .amount { text-align: right; }
.rui-payment .amount b { font: 600 24px ui-monospace, Menlo, monospace; }
.rui-payment .body { display: grid; grid-template-columns: 196px 1fr; }
.rui-payment .order { background: #f1f4f9; padding: 16px 18px; border-right: 1px solid #e2e7f0; }
.rui-payment .order p { margin: 0 0 10px; }
.rui-payment .item { display: grid; grid-template-columns: 28px 1fr auto; gap: 8px; align-items: center; font-size: 13px; }
.rui-payment .item i { width: 28px; height: 28px; border-radius: 7px; }
.rui-payment .item small { display: block; color: #6b7280; font-size: 12px; }
.rui-payment .shoes { background: linear-gradient(135deg, #f97316, #e11d48); }
.rui-payment .socks { background: linear-gradient(135deg, #22c55e, #0d9488); }
.rui-payment .total { display: flex; justify-content: space-between; border-top: 1px solid #dfe5ee; padding-top: 8px; font-weight: 700; }
.rui-payment .card { display: grid; gap: 2px; border-radius: 10px; padding: 10px 12px; background: linear-gradient(135deg, #1e293b, #475569); color: #fff; font: 13px ui-monospace, Menlo, monospace; }
.rui-payment .card b { color: #facc15; font: 800 12px system-ui; letter-spacing: .08em; }
.rui-payment .card small { font: 11px system-ui; color: #cbd5e1; }
.rui-payment .steps { list-style: none; margin: 0; padding: 14px 16px; display: grid; gap: 6px; }
.rui-payment .steps li { display: grid; grid-template-columns: 60px 1fr; gap: 12px; align-items: center; padding: 7px; border-radius: 12px; }
.rui-payment .steps li > span { grid-column: 2; }
.rui-payment .steps li b { display: block; }
.rui-payment .steps li small { color: #6b7280; }
.rui-payment .icon { display: block; width: 60px; height: 60px; padding: 4px; box-sizing: border-box; border-radius: 12px; background: #fff; border: 1px solid #e2e8f0; }
.rui-payment .done .icon { background: #ecfdf5; border-color: #a7f3d0; }
.rui-payment .steps .done small { color: #15803d; font-weight: 600; }
.rui-payment .running { background: linear-gradient(135deg, #1e3a8a, #2563eb); color: #fff; }
.rui-payment .steps .running small { color: #bfdbfe; }
.rui-payment .next .icon { background: #f1f5f9; }
.rui-payment .next .icon > * { opacity: .45; filter: grayscale(1); }
.rui-payment .next b { color: #94a3b8; }

.rui-pipeline .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-pipeline .rui-main { width: 560px; margin: 14px auto; background: #0b0f17; color: #d1d5db; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-pipeline .head { display: flex; align-items: center; gap: 10px; padding: 13px 18px; border-bottom: 1px solid #1f2937; }
.rui-pipeline .head b { color: #fff; font-size: 15px; }
.rui-pipeline .head small { color: #9ca3af; }
.rui-pipeline .pill { margin-left: auto; font: 600 12px system-ui; border-radius: 999px; padding: 3px 10px; background: #1e3a8a; color: #bfdbfe; }
.rui-pipeline .ok { background: #14532d; color: #bbf7d0; }
.rui-pipeline .flow { display: block; width: 520px; height: 160px; margin: 18px auto 4px; }
.rui-pipeline .names { display: grid; grid-template-columns: repeat(3, 1fr); text-align: center; font-size: 13px; color: #9ca3af; margin: 0 20px 14px; }
.rui-pipeline .names b { display: block; color: #fff; }
.rui-pipeline .bar { height: 6px; border-radius: 3px; background: #1f2937; margin: 0 20px 18px; overflow: hidden; }
.rui-pipeline .bar i { display: block; height: 100%; background: #22c55e; }

.rui-weather .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-weather .rui-main { width: 400px; margin: 14px auto; color: #fff; background: radial-gradient(120% 90% at 85% 0%, #1e293b 0%, #0b1220 60%, #070b14 100%); border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-weather .now { display: grid; grid-template-columns: 1fr auto; align-items: center; padding: 18px 20px 4px; }
.rui-weather .now small { display: block; opacity: .7; }
.rui-weather .now b { display: block; font: 300 60px/1 system-ui; margin: 6px 0; }
.rui-weather .now span { color: #cbd5e1; }
.rui-weather .big { display: block; width: 160px; height: 160px; margin: -12px -10px -12px 0; }
.rui-weather .days { display: grid; grid-template-columns: repeat(5, 1fr); list-style: none; margin: 0; padding: 6px 10px 16px; text-align: center; font-size: 13px; border-top: 1px solid rgba(255, 255, 255, .08); }
.rui-weather .days small { display: block; color: #94a3b8; padding-top: 8px; }
.rui-weather .days li > :nth-child(2) { display: block; width: 56px; height: 56px; margin: 0 auto; }

