.rui-dashboard .feed header { display: flex; justify-content: space-between; padding: 12px 18px 8px; }
.rui-dashboard .feed a { color: #2563eb; font-size: 13px; text-decoration: none; }
.rui-dashboard .item { display: grid; grid-template-columns: 58px 1fr; gap: 14px; align-items: center; padding: 10px 18px; border-top: 1px solid #f1f5f9; }
.rui-dashboard .icon { display: block; width: 58px; height: 58px; border-radius: 12px; background: #fff7f3; }
.rui-dashboard .item small { display: block; font: 600 11px system-ui; letter-spacing: .08em; color: #c2410c; }
.rui-dashboard .item b { display: block; font-size: 15px; }
.rui-dashboard .item p { margin: 2px 0 0; color: #4b5563; font-size: 13.5px; }

.rui-notfound .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-notfound .rui-main { width: 560px; margin: 14px auto; color: #fff; text-align: center; background: linear-gradient(180deg, #0a1a3a 0%, #13336b 65%, #1c4a8f 100%); border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-notfound .message { display: grid; justify-items: center; gap: 6px; padding: 24px 24px 0; }
.rui-notfound .message small { font: 600 13px ui-monospace, Menlo, monospace; letter-spacing: .1em; color: #93c5fd; }
.rui-notfound .message h1 { margin: 0; font-size: 24px; }
.rui-notfound .message p { margin: 0; color: #bfdbfe; }
.rui-notfound .message button { margin-top: 8px; border: 0; border-radius: 10px; padding: 9px 16px; background: #fff; color: #13336b; font: 600 14px system-ui; }
.rui-notfound .scene { position: relative; height: 290px; }
.rui-notfound .sea { position: absolute; left: 0; right: 0; bottom: 0; display: block; width: 100%; height: 144px; }
.rui-notfound .boat { position: relative; display: block; width: 440px; height: 220px; margin: 10px auto 0; }

.rui-hover .rui-main { font: 14px/1.45 system-ui, sans-serif; color: #1f2937; }
.rui-hover .rui-main { width: 440px; margin: 40px auto; padding: 16px 18px; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(15, 23, 42, .14); }
.rui-hover .file { display: grid; grid-template-columns: 44px 1fr; gap: 12px; align-items: center; margin-bottom: 14px; }
.rui-hover .file i { width: 44px; height: 52px; border-radius: 6px; background: #fee2e2; display: grid; place-items: center; color: #b91c1c; font: 700 11px system-ui; font-style: normal; }
.rui-hover .file small { display: block; color: #6b7280; font-size: 12.5px; }
.rui-hover .actions { display: flex; gap: 8px; }
.rui-hover .space { flex: 1; }
.rui-hover .act { display: inline-flex; align-items: center; gap: 8px; height: 44px; padding: 0 16px 0 10px; border: 1px solid #e5e7eb; border-radius: 8px; background: #fff; color: #334155; font: 600 14px system-ui; }
.rui-hover .act:hover { border-color: #c7d2fe; background: #eef2ff; color: #3730a3; }
.rui-hover .danger:hover { border-color: #fecaca; background: #fef2f2; color: #b91c1c; }
.rui-hover .ok, .rui-hover .ok:hover { background: #2563eb; border-color: #2563eb; color: #fff; }
.rui-hover .icon { display: block; width: 30px; height: 30px; }

