type HoverButtonProps = {
  icon: PxAnimatedSvgDocument;
  label: string;
  className: string;
};

function HoverButton({ icon, label, className }: HoverButtonProps) {
  const api = useRef<ReactAnimatorApi>(null);
  const play = (rate: number) => {
    api.current?.setPlaybackRate(rate);
    api.current?.play();
  };
  return (
    <button className={className}
      onMouseEnter={() => play(1)} onMouseLeave={() => play(-1)}>
      <PixodeskSvgAnimator className="icon" doc={icon} apiRef={api} />
      {label}
    </button>
  );
}

<HoverButton className="act danger" icon={trash} label="Delete" />
<span className="space" />
<HoverButton className="act" icon={cancel} label="Cancel" />
<HoverButton className="act ok" icon={ok} label="OK" />

